module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    input  logic dig,
    output logic walk_left,
    output logic walk_right,
    output logic aaah,
    output logic digging
);

    typedef enum logic [2:0] {
        S_WALK_LEFT  = 3'd0,
        S_WALK_RIGHT = 3'd1,
        S_DIG_LEFT   = 3'd2,
        S_DIG_RIGHT  = 3'd3,
        S_FALL_LEFT  = 3'd4,
        S_FALL_RIGHT = 3'd5,
        S_SPLATTER   = 3'd6
    } state_t;

    state_t state, next_state;
    logic [5:0] fall_cnt;

    // State register and fall counter
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S_WALK_LEFT;
            fall_cnt <= 6'd0;
        end else begin
            state <= next_state;
            if (next_state == S_FALL_LEFT || next_state == S_FALL_RIGHT) begin
                if (fall_cnt < 6'd63)
                    fall_cnt <= fall_cnt + 1'b1;
            end else begin
                fall_cnt <= 6'd0;
            end
        end
    end

    // Next state logic
    always_comb begin
        next_state = state;
        case (state)
            S_WALK_LEFT: begin
                if (!ground)
                    next_state = S_FALL_LEFT;
                else if (dig)
                    next_state = S_DIG_LEFT;
                else if (bump_left || bump_right)
                    next_state = S_WALK_RIGHT;
                else
                    next_state = S_WALK_LEFT;
            end

            S_WALK_RIGHT: begin
                if (!ground)
                    next_state = S_FALL_RIGHT;
                else if (dig)
                    next_state = S_DIG_RIGHT;
                else if (bump_left || bump_right)
                    next_state = S_WALK_LEFT;
                else
                    next_state = S_WALK_RIGHT;
            end

            S_DIG_LEFT: begin
                if (!ground)
                    next_state = S_FALL_LEFT;
                else
                    next_state = S_DIG_LEFT;
            end

            S_DIG_RIGHT: begin
                if (!ground)
                    next_state = S_FALL_RIGHT;
                else
                    next_state = S_DIG_RIGHT;
            end

            S_FALL_LEFT: begin
                if (ground) begin
                    if (fall_cnt > 6'd20)
                        next_state = S_SPLATTER;
                    else
                        next_state = S_WALK_LEFT;
                end else begin
                    next_state = S_FALL_LEFT;
                end
            end

            S_FALL_RIGHT: begin
                if (ground) begin
                    if (fall_cnt > 6'd20)
                        next_state = S_SPLATTER;
                    else
                        next_state = S_WALK_RIGHT;
                end else begin
                    next_state = S_FALL_LEFT; // wait, should be S_FALL_RIGHT!
                end
            end

            S_SPLATTER: begin
                next_state = S_SPLATTER;
            end

            default: begin
                next_state = S_WALK_LEFT;
            end
        endcase
    end

    // Output logic (Moore outputs)
    always_comb begin
        walk_left = 1'b0;
        walk_right = 1'b0;
        aaah = 1'b0;
        digging = 1'b0;

        case (state)
            S_WALK_LEFT:  walk_left = 1'b1;
            S_WALK_RIGHT: walk_right = 1'b1;
            S_DIG_LEFT,
            S_DIG_RIGHT:  digging = 1'b1;
            S_FALL_LEFT,
            S_FALL_RIGHT: aaah = 1'b1;
            S_SPLATTER:   ; // all 0
            default:      ;
        endcase
    end

endmodule

